    apply (lap_of_run tm Cc true true cho_1RB1LD_1RC0RC_0LD0RC_1LA0LD B0_1RB1LD_1RC0RC_0LD0RC_1LA0LD B1_1RB1LD_1RC0RC_0LD0RC_1LA0LD 4 8 p j' [] []).
