(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1LD_1RC0RC_0LD0RC_1LA1LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Bp q0 ++ [S0]) [] 0 Z0_1RB1LD_1RC0RC_0LD0RC_1LA1LD /\
  cden (Bp q0 ++ [S0]) [] 0 Z1_1RB1LD_1RC0RC_0LD0RC_1LA1LD = Cc (Pos.succ p).
Proof.
