Lemma gp_1RB1LD_1RC0RC_0LD0RC_1LA1LD : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Bp q0 ++ [S0]) [] j P0_1RB1LD_1RC0RC_0LD0RC_1LA1LD /\
  cden (Bp q0 ++ [S0]) [] j P1_1RB1LD_1RC0RC_0LD0RC_1LA1LD = Cc (Pos.succ p).
