Lemma lapi_1RB1LD_1RC0RC_0LD0RC_1LA1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
