  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1LD_1RC0RC_0LD0RC_1LA1LD p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1LD_1RC0RC_0LD0RC_1LA1LD Z0_1RB1LD_1RC0RC_0LD0RC_1LA1LD Z1_1RB1LD_1RC0RC_0LD0RC_1LA1LD 0 4
               run_z_1RB1LD_1RC0RC_0LD0RC_1LA1LD (Bp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1LD_1RC0RC_0LD0RC_1LA1LD p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1LD_1RC0RC_0LD0RC_1LA1LD P0_1RB1LD_1RC0RC_0LD0RC_1LA1LD P1_1RB1LD_1RC0RC_0LD0RC_1LA1LD 4 8
               run_p_1RB1LD_1RC0RC_0LD0RC_1LA1LD (Bp q0 ++ [S0]) [] j'
