(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LD_1RC0RC_0LD1RB_1RC1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LD_1RC0RC_0LD1RB_1RC1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LD_1RC0RC_0LD1RB_1RC1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LD_1RC0RC_0LD1RB_1RC1LA p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1LD_1RC0RC_0LD1RB_1RC1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LD_1RC0RC_0LD1RB_1RC1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LD_1RC0RC_0LD1RB_1RC1LA t p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB1LD_1RC0RC_0LD1RB_1RC1LA). split;
      [| exact (gbo_1RB1LD_1RC0RC_0LD1RB_1RC1LA j)].
    rewrite (gso_1RB1LD_1RC0RC_0LD1RB_1RC1LA p j E).
    exact (srun_sound tm true true chb_1RB1LD_1RC0RC_0LD1RB_1RC1LA B0_1RB1LD_1RC0RC_0LD1RB_1RC1LA BB1_1RB1LD_1RC0RC_0LD1RB_1RC1LA 4 8
             run_boot_1RB1LD_1RC0RC_0LD1RB_1RC1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1LD_1RC0RC_0LD1RB_1RC1LA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1LD_1RC0RC_0LD1RB_1RC1LA j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LD_1RC0RC_0LD1RB_1RC1LA : forall t, ~ In t pins_1RB1LD_1RC0RC_0LD1RB_1RC1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1LD_1RC0RC_0LD1RB_1RC1LA.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LD_1RC0RC_0LD1RB_1RC1LA (StA, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LD_1RC0RC_0LD1RB_1RC1LA [SWinR 2; SCycL 2 0; SWin 2; SWinL 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_1RC0RC_0LD1RB_1RC1LA [SWinR 2; SCycL 2 0; SWin 1] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_1RC0RC_0LD1RB_1RC1LA [SWinR 2; SCycL 2 0; SWin 4] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_1RC0RC_0LD1RB_1RC1LA [SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_1RC0RC_0LD1RB_1RC1LA [SWinR 2; SCycL 2 0; SWin 3] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_1RC0RC_0LD1RB_1RC1LA [] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_1RC0RC_0LD1RB_1RC1LA [SWinR 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem qhtr_1RB1LD_1RC0RC_0LD1RB_1RC1LA : NonHalt tm_1RB1LD_1RC0RC_0LD1RB_1RC1LA /\ QHBoundTr 32779478 tm_1RB1LD_1RC0RC_0LD1RB_1RC1LA /\ QuasiHaltsTr tm_1RB1LD_1RC0RC_0LD1RB_1RC1LA.
Proof.
  apply (lap_qh_stage tm_1RB1LD_1RC0RC_0LD1RB_1RC1LA pins_1RB1LD_1RC0RC_0LD1RB_1RC1LA Cc 2 19 32779478).
