  - destruct (lapi_1RB1LD_1RC1LA_0LD0RC_1LB1LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LD_1RC1LA_0LD0RC_1LB1LC B0_1RB1LD_1RC1LA_0LD0RC_1LB1LC B1_1RB1LD_1RC1LA_0LD0RC_1LB1LC 8 12 p j' [] []).
