Lemma epow2_1RB1LD_1RC1LA_1LC0RB_1RC0LA : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB1LD_1RC1LA_1LC0RB_1RC0LA : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1] [] 0 0 []).
Definition AI1_1RB1LD_1RC1LA_1LC0RB_1RC0LA : sconf := mkC StA (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1] [] 0 0 []).
Definition chn_1RB1LD_1RC1LA_1LC0RB_1RC0LA : list lstep := [SWin 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_inner_1RB1LD_1RC1LA_1LC0RB_1RC0LA : srun tm false true chn_1RB1LD_1RC1LA_1LC0RB_1RC0LA AI0_1RB1LD_1RC1LA_1LC0RB_1RC0LA = Some (AI1_1RB1LD_1RC1LA_1LC0RB_1RC0LA, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1LD_1RC1LA_1LC0RB_1RC0LA : sconf := mkC StA (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1] [] 0 0 []).
Definition chb_1RB1LD_1RC1LA_1LC0RB_1RC0LA : list lstep := [SWin 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_boot_1RB1LD_1RC1LA_1LC0RB_1RC0LA : srun tm true true chb_1RB1LD_1RC1LA_1LC0RB_1RC0LA B0_1RB1LD_1RC1LA_1LC0RB_1RC0LA = Some (BB1_1RB1LD_1RC1LA_1LC0RB_1RC0LA, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1LD_1RC1LA_1LC0RB_1RC0LA : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [S1] [] 0 0 []).
Definition che_1RB1LD_1RC1LA_1LC0RB_1RC0LA : list lstep := [SWin 2; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 2; SRotL 2; SFoldL 1].

Lemma run_exit_1RB1LD_1RC1LA_1LC0RB_1RC0LA : srun tm true true che_1RB1LD_1RC1LA_1LC0RB_1RC0LA BE0_1RB1LD_1RC1LA_1LC0RB_1RC0LA = Some (B1_1RB1LD_1RC1LA_1LC0RB_1RC0LA, 4, 10).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LD_1RC1LA_1LC0RB_1RC0LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ip q0 ++ [S0]) [] j A0_1RB1LD_1RC1LA_1LC0RB_1RC0LA.
Proof.
  intros p j q0 E. destruct (ILCounter.cview_some_I p j q0 E) as (H1 & _).
  unfold Cc_1RB1LD_1RC1LA_1LC0RB_1RC0LA, cden, A0_1RB1LD_1RC1LA_1LC0RB_1RC0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB1LD_1RC1LA_1LC0RB_1RC0LA : forall p j q0, cview p = (j, Some q0) ->
  cden (Ip q0 ++ [S0]) [] j A1_1RB1LD_1RC1LA_1LC0RB_1RC0LA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (ILCounter.cview_some_I p j q0 E) as (_ & H2).
  unfold Cc_1RB1LD_1RC1LA_1LC0RB_1RC0LA, cden, A1_1RB1LD_1RC1LA_1LC0RB_1RC0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LD_1RC1LA_1LC0RB_1RC0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 8). split; [lia|].
  rewrite (gsi_1RB1LD_1RC1LA_1LC0RB_1RC0LA p j q0 E).
  rewrite (srun_sound tm false true chi_1RB1LD_1RC1LA_1LC0RB_1RC0LA A0_1RB1LD_1RC1LA_1LC0RB_1RC0LA A1_1RB1LD_1RC1LA_1LC0RB_1RC0LA 4 8
             run_int_1RB1LD_1RC1LA_1LC0RB_1RC0LA (Ip q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB1LD_1RC1LA_1LC0RB_1RC0LA p j q0 E).
Qed.

Lemma gso_1RB1LD_1RC1LA_1LC0RB_1RC0LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LD_1RC1LA_1LC0RB_1RC0LA.
Proof.
  intros p j E. destruct (ILCounter.cview_none_I p j E) as (H1 & _).
  unfold Cc_1RB1LD_1RC1LA_1LC0RB_1RC0LA, cden, B0_1RB1LD_1RC1LA_1LC0RB_1RC0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1LD_1RC1LA_1LC0RB_1RC0LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LD_1RC1LA_1LC0RB_1RC0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LD_1RC1LA_1LC0RB_1RC0LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (ILCounter.cview_none_I p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LD_1RC1LA_1LC0RB_1RC0LA
             = (StA, (rep [S1;S0] (S j) ++ [S1], S0, [S1]))).
  { unfold cden, B1_1RB1LD_1RC1LA_1LC0RB_1RC0LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S1;S0] (S j) ++ [S1]) ++ [S0], S0, [S1]))).
  { unfold Cc_1RB1LD_1RC1LA_1LC0RB_1RC0LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1LD_1RC1LA_1LC0RB_1RC0LA. reflexivity.
Qed.

