  exact (srun_sound tm false true chn_1RB1LD_1RC1LA_1LC0RB_1RC0LA AI0_1RB1LD_1RC1LA_1LC0RB_1RC0LA AI1_1RB1LD_1RC1LA_1LC0RB_1RC0LA 4 8
