(** 1RB1LD_1RC1RA_0LA0RB_0RB0LD *)
(** 1RB1LD_1RC1RA_0LA0RB_0RB0LD -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB1LD_1RC1RA_0LA0RB_0RB0LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StD
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S0 DL StA | StC, S1 => mk S0 DR StB
  | StD, S0 => mk S0 DR StB | StD, S1 => mk S0 DL StD end.

(** Its mirror 1LB1RD_1LC1LA_0RA0LB_0LB0RD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1LD_1RC1RA_0LA0RB_0RB0LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DR StD
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DL StA
  | StC, S0 => mk S0 DR StA | StC, S1 => mk S0 DL StB
  | StD, S0 => mk S0 DL StB | StD, S1 => mk S0 DR StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LD_1RC1RA_0LA0RB_0RB0LD : list Instr := [(StC, S1)].
Definition tmw_1RB1LD_1RC1RA_0LA0RB_0RB0LD : TM := tm_wrap_trs tmm_1RB1LD_1RC1RA_0LA0RB_0RB0LD pins_1RB1LD_1RC1RA_0LA0RB_0RB0LD.
Local Notation tm := tmw_1RB1LD_1RC1RA_0LA0RB_0RB0LD.

Lemma mirror_ok_1RB1LD_1RC1RA_0LA0RB_0RB0LD : mirror_tm tm_1RB1LD_1RC1RA_0LA0RB_0RB0LD = tmm_1RB1LD_1RC1RA_0LA0RB_0RB0LD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB1LD_1RC1RA_0LA0RB_0RB0LD (p : positive) : cconf := (StD, (Ap_Alph_00_10_1 p ++ [S0], S0, [S1])).
