(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_1RB1LD_1RC1RA_0LA0RB_0RB0LD : sconf := mkC StD (mkS [S0;S0] [] 0 0 []) S0 (mkS [S1] [] 0 0 []).
Definition Z1_1RB1LD_1RC1RA_0LA0RB_0RB0LD : sconf := mkC StD (mkS [S1;S0] [] 0 0 []) S0 (mkS [S1] [] 0 0 []).
Definition chz_1RB1LD_1RC1RA_0LA0RB_0RB0LD : list lstep := [SWin 4].

Lemma run_z_1RB1LD_1RC1RA_0LA0RB_0RB0LD : srun tm false true chz_1RB1LD_1RC1RA_0LA0RB_0RB0LD Z0_1RB1LD_1RC1RA_0LA0RB_0RB0LD = Some (Z1_1RB1LD_1RC1RA_0LA0RB_0RB0LD, 0, 4).
