  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RA_0LC1RD_1LA1LC_0LC0RD B0_1RB1RA_0LC1RD_1LA1LC_0LC0RD B1_1RB1RA_0LC1RD_1LA1LC_0LC0RD 4 8 p j' [] []).
