      with (l := [SCycL 2 0; SWin 2; SWinL 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RA_1LC0RA_1RC0LD_0LC1LA
      with (l := [SCycL 2 0; SWin 2; SWinL 3]).
