    apply (lap_of_run tm Cc true true cho_1RB1RA_1LC0RB_0RA1LD_0RB0LD B0_1RB1RA_1LC0RB_0RA1LD_0RB0LD B1_1RB1RA_1LC0RB_0RA1LD_0RB0LD 4 12 p j' [] []).
    + exact run_ovf_1RB1RA_1LC0RB_0RA1LD_0RB0LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RA_1LC0RB_0RA1LD_0RB0LD p j' E).
    + exact (geo_1RB1RA_1LC0RB_0RA1LD_0RB0LD p j' E).
    + lia.
